def move_people(apps, schema_editor):
    """Shaxsiyatlar (sportchilar, davlat mukofoti sohiblari) -> Bizning qahramonlar."""
    Person = apps.get_model("core", "Person")
    Hero = apps.get_model("core", "Hero")
    Bookmark = apps.get_model("core", "Bookmark")
    Photo = apps.get_model("core", "Photo")
    ContentType = apps.get_model("contenttypes", "ContentType")
    start = Hero.objects.count()
    for i, p in enumerate(Person.objects.filter(person_type="shaxs").order_by("order", "full_name")):
        cat = "sportchi" if "/athletes" in (p.source_url or "") or "sportchi" in (p.position or "").lower() else "mukofot"
        slug = p.slug
        if Hero.objects.filter(slug=slug).exists():
            slug = f"{slug}-{p.pk}"
        h = Hero.objects.create(
            full_name=p.full_name, slug=slug, category=cat, rank=p.position or "", birth_date=p.birth_date,
            bio=p.bio, awards=p.awards, photo=p.photo.name if p.photo else "", source_url=p.source_url or "",
            department_id=p.department_id, views=p.views, order=start + i + 1,
        )
        Bookmark.objects.filter(content_type="shaxs", object_id=p.pk).update(content_type="qahramon", object_id=h.pk)
        try:
            ct_p = ContentType.objects.get(app_label="core", model="person")
            ct_h = ContentType.objects.get(app_label="core", model="hero")
            Photo.objects.filter(content_type=ct_p, object_id=p.pk).update(content_type=ct_h, object_id=h.pk)
        except ContentType.DoesNotExist:
            pass
        p.delete()


def back(apps, schema_editor):
    Person = apps.get_model("core", "Person")
    Hero = apps.get_model("core", "Hero")
    for h in Hero.objects.exclude(category="halok"):
        Person.objects.create(full_name=h.full_name, slug=h.slug, person_type="shaxs", position=h.rank,
                              birth_date=h.birth_date, bio=h.bio, awards=h.awards,
                              photo=h.photo.name if h.photo else "", source_url=h.source_url, order=100 + h.order)
        h.delete()



